import{_ as a,o,c as r,a2 as c}from"./chunks/framework.BS0bAV7E.js";const p=JSON.parse('{"title":"内存管理","description":"","frontmatter":{},"headers":[],"relativePath":"zh/arch/memory.md","filePath":"zh/arch/memory.md"}'),t={name:"zh/arch/memory.md"};function m(d,e,l,h,i,n){return o(),r("div",null,[...e[0]||(e[0]=[c('<h1 id="内存管理" tabindex="-1">内存管理 <a class="header-anchor" href="#内存管理" aria-label="Permalink to &quot;内存管理&quot;">​</a></h1><h2 id="pmm-物理页存储" tabindex="-1">PMM - 物理页存储 <a class="header-anchor" href="#pmm-物理页存储" aria-label="Permalink to &quot;PMM - 物理页存储&quot;">​</a></h2><p><code>kernel/mem/mem_pmm.{c,h}</code>：基于 multiboot2 内存映射构建的 4 KiB 页框位图。保留区域（内核镜像、帧缓冲、MBI 本身）在初始化时被标记为已使用。O(1) 分配和释放。<code>memtest</code> / <code>pmmrace</code> 在客户机内对其进行测试。</p><h2 id="vmm-四级分页" tabindex="-1">VMM - 四级分页 <a class="header-anchor" href="#vmm-四级分页" aria-label="Permalink to &quot;VMM - 四级分页&quot;">​</a></h2><p><code>kernel/mem/mem_vmm.{c,h}</code>：内核保留 boot.S 对低 4 GiB 的恒等映射；VMM 为用户进程创建和编辑额外的地址空间。保护标志映射到读/写/nx/用户位。<code>vmtest</code>、<code>vmmap</code>、<code>vmkernelpt</code>、<code>cr3test</code> 实时检查它。</p><h2 id="堆-kmalloc-kfree" tabindex="-1">堆 - kmalloc/kfree <a class="header-anchor" href="#堆-kmalloc-kfree" aria-label="Permalink to &quot;堆 - kmalloc/kfree&quot;">​</a></h2><p><code>kernel/mem/mem_heap.{c,h}</code>：空闲链表、首次适配、合并；块按 16 字节对齐（头文件恰好 32 字节 - 一个历史性的交替奇偶校验错误导致负载对齐依赖于分配奇偶性，这进而移动了 ATA-DMA PRDT 窗口并破坏了 FAT32 挂载；头文件大小现在是静态断言的）。16 MiB 快速失败上限；<code>heaptest</code> + <code>heapbounds</code> 是测试，<code>heap</code>/<code>frag</code> 是检查工具。</p><h2 id="通过异常实现增长" tabindex="-1">通过异常实现增长 <a class="header-anchor" href="#通过异常实现增长" aria-label="Permalink to &quot;通过异常实现增长&quot;">​</a></h2><p>栈增长和堆增长 #PF 在异常路径中处理：任务栈指针下方且在其栈区域内的故障会映射一个新页面；堆增长会映射支持页面；其他任何情况都会升级到崩溃路径。<code>exc</code> 每次启动都证明陷阱机制。</p><h2 id="dma-约束" tabindex="-1">DMA 约束 <a class="header-anchor" href="#dma-约束" aria-label="Permalink to &quot;DMA 约束&quot;">​</a></h2><p>将物理地址编程到设备结构中的驱动程序验证对齐，并且对于 32 位 DMA 掩码，验证地址低于 4 GiB（xHCI 在探测和每次传输时都拒绝高于 4GiB 的 DMA；ATA-DMA 掩蔽 PRDT）。这就是为什么堆的对齐保证是承重的。</p>',11)])])}const _=a(t,[["render",m]]);export{p as __pageData,_ as default};
